function prng(seed){var a=seed>>>0||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var R=prng(58001);
var T0=Date.now();
var N=10,K=2,P=0.2;
var dur=[],deps=[];
for(var i=0;i<N;i++){dur.push(1+Math.floor(R()*9));deps.push([]);}
for(var i=0;i<N;i++)for(var j=i+1;j<N;j++)if(R()<P)deps[j].push(i);
var done=new Array(N).fill(false),endT=new Array(N).fill(0),wf=new Array(K).fill(0);
var serial=dur.reduce(function(a,b){return a+b;},0),remaining=N,guard=0;
while(remaining>0&&guard++<N*20){
  var ready=[];
  for(var i=0;i<N;i++)if(!done[i]&&deps[i].every(function(d){return done[d];}))ready.push(i);
  if(!ready.length)break;
  ready.sort(function(a,b){return dur[b]-dur[a];});
  var ti=ready[0];
  var est=deps[ti].reduce(function(a,d){return Math.max(a,endT[d]);},0);
  var wI=0;for(var k=1;k<K;k++)if(wf[k]<wf[wI])wI=k;
  var st=Math.max(est,wf[wI]);wf[wI]=st+dur[ti];endT[ti]=st+dur[ti];done[ti]=true;remaining--;
}
var makespan=Math.max.apply(null,wf);
console.log(JSON.stringify({id:"JAH-APX58-000001",ok:true,metrics:{tasks:N,workers:K,makespan:makespan,serial:serial,speedup:+(serial/makespan).toFixed(2),complete:remaining===0},ms:Date.now()-T0}));

